CREATE TABLE locations (id VARCHAR(64) PRIMARY KEY, case_id VARCHAR(191) NOT NULL, location_text TEXT NOT NULL, location_precision VARCHAR(16) NOT NULL DEFAULT 'unknown', location_kind VARCHAR(32) NULL, longitude DOUBLE NULL CHECK (longitude BETWEEN -180 AND 180), latitude DOUBLE NULL CHECK (latitude BETWEEN -90 AND 90), location_radius_meters DOUBLE NULL CHECK (location_radius_meters >= 0), status VARCHAR(16) NOT NULL DEFAULT 'active', merged_into_id VARCHAR(64) NULL, created_by_user_id VARCHAR(191) NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, CONSTRAINT chk_locations_precision CHECK (location_precision IN ('unknown','approximate','address','coordinates')), CONSTRAINT chk_locations_status CHECK (status IN ('active','merged','retired')), CONSTRAINT fk_locations_case FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE, CONSTRAINT fk_locations_merged_into FOREIGN KEY (merged_into_id) REFERENCES locations(id) ON DELETE SET NULL, CONSTRAINT fk_locations_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL);
-- statement-break
CREATE INDEX idx_locations_case_status ON locations(case_id, status, updated_at);
